import os, re
# Read .dockerignore
patterns = []
with open('.dockerignore') as f:
    for line in f:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        patterns.append(line)

# Check if data/ matches any pattern
def matches(path, patterns):
    for pat in patterns:
        # Simple contains/glob match
        if pat.endswith('/'):
            if path.startswith(pat) or path == pat.rstrip('/'):
                return True
        else:
            # fnmatch
            import fnmatch
            if fnmatch.fnmatch(path, pat) or fnmatch.fnmatch(os.path.basename(path), pat):
                return True
    return False

for p in ['data', 'data/', 'data/1.txt', 'data/foo.txt']:
    print(f'{p!r} excluded? {matches(p, patterns)}')

print()
print('All patterns:')
for p in patterns:
    print(f'  {p!r}')
